"""Offline catalog entries for the separately modeled club."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ROWS=[['Live chess club · full 3D', 'Club de ajedrez animado · 3D completo', 'Club animé · entièrement en 3D', 'Lebendiger Schachclub · vollständig 3D', 'Clube de xadrez animado · 3D completo', 'Circolo animato · interamente 3D', 'Levende schaakclub · volledig 3D', 'Żywy klub szachowy · pełne 3D'], ['Quiet has two players. Club and Busy add two players and two individual visitors who arrive, watch games and leave.', 'Tranquila tiene dos jugadores. Club y Animada añaden dos jugadores y dos visitantes diferentes que llegan, observan partidas y se marchan.', 'Calme accueille deux joueurs. Club et Animée ajoutent deux joueurs et deux visiteurs distincts qui arrivent, regardent les parties et repartent.', 'Ruhig zeigt zwei Spieler. Verein und Belebt ergänzen zwei Spieler und zwei individuelle Besucher, die kommen, Partien verfolgen und gehen.', 'Tranquila tem dois jogadores. Clube e Movimentada acrescentam dois jogadores e dois visitantes diferentes que chegam, observam partidas e saem.', 'Tranquilla ha due giocatori. Circolo e Animata aggiungono due giocatori e due visitatori diversi che arrivano, osservano le partite e vanno via.', 'Rustig heeft twee spelers. Club en Druk voegen twee spelers en twee verschillende bezoekers toe die binnenkomen, partijen bekijken en vertrekken.', 'Spokojna ma dwóch graczy. Klubowa i Żywa dodają dwóch graczy i dwie różne osoby, które przychodzą, obserwują partie i wychodzą.'], ['The club has six individual characters. Background games are illustrative opening studies. The clock beside your board shows game time; the wall clock follows your computer. Hidden boards pause animation.', 'El club tiene seis personajes diferentes. Las partidas de fondo son estudios de apertura ilustrativos. El reloj junto al tablero muestra el tiempo de la partida; el reloj de pared sigue la hora del equipo. La animación se pausa al ocultar el tablero.', 'Le club compte six personnages distincts. Les parties de fond illustrent des études d’ouvertures. La pendule près du plateau affiche le temps de jeu ; l’horloge murale suit votre ordinateur. Masquer l’échiquier suspend l’animation.', 'Der Club hat sechs individuelle Figuren. Hintergrundpartien veranschaulichen Eröffnungsstudien. Die Brettuhr zeigt die Spielzeit; die Wanduhr folgt der Computerzeit. Verborgene Bretter pausieren die Animation.', 'O clube tem seis personagens distintos. As partidas ao fundo ilustram estudos de aberturas. O relógio ao lado do tabuleiro mostra o tempo da partida; o relógio de parede segue o computador. Tabuleiros ocultos pausam a animação.', 'Il circolo ha sei personaggi diversi. Le partite sullo sfondo illustrano studi di aperture. L’orologio accanto alla scacchiera mostra il tempo di gioco; quello a parete segue il computer. Nascondere la scacchiera sospende l’animazione.', 'De club heeft zes verschillende personages. De achtergrondpartijen zijn illustratieve openingsstudies. De klok naast je bord toont speeltijd; de wandklok volgt je computer. Verborgen borden pauzeren de animatie.', 'Klub ma sześć różnych postaci. Partie w tle ilustrują analizę debiutów. Zegar obok szachownicy pokazuje czas gry, a zegar ścienny czas komputera. Ukrycie szachownicy wstrzymuje animację.'], ['Use computer time for daylight', 'Usar la hora del equipo para la luz exterior', 'Adapter la lumière extérieure à l’heure de l’ordinateur', 'Tageslicht nach Computerzeit', 'Usar a hora do computador para a luz exterior', 'Usa l’ora del computer per la luce esterna', 'Daglicht volgens computertijd', 'Światło dzienne według czasu komputera'], ['Local-time daylight uses dawn from 06:00 to 08:00 and dusk from 18:00 to 20:00. Turn it off to use a lighting preset.', 'La luz exterior usa el amanecer de 06:00 a 08:00 y el anochecer de 18:00 a 20:00, hora local. Desactívela para usar un ajuste de iluminación.', 'La lumière suit l’heure locale : aube de 06:00 à 08:00, crépuscule de 18:00 à 20:00. Désactivez-la pour utiliser un préréglage.', 'Tageslicht nach Ortszeit: Morgendämmerung 06:00–08:00, Abenddämmerung 18:00–20:00. Ausschalten, um eine Lichtvoreinstellung zu nutzen.', 'A luz segue a hora local: amanhecer das 06:00 às 08:00 e entardecer das 18:00 às 20:00. Desative para usar uma predefinição.', 'La luce segue l’ora locale: alba dalle 06:00 alle 08:00, tramonto dalle 18:00 alle 20:00. Disattivala per usare una preimpostazione.', 'Daglicht volgt de lokale tijd: dageraad 06:00–08:00 en schemering 18:00–20:00. Zet dit uit voor een lichtpreset.', 'Światło według czasu lokalnego: świt 06:00–08:00, zmierzch 18:00–20:00. Wyłącz, aby użyć ustawienia oświetlenia.']]
for i,lang in enumerate(('en','es','fr','de','pt','it','nl','pl')):
 p=ROOT/'locales'/f'{lang}.json';data=json.loads(p.read_text(encoding='utf-8'))
 for row in ROWS:data['messages'][row[0]]=row[i]
 p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Club controls translated in eight languages')
